<style>
/* ===== Ultra Modern Announcement Bar ===== */
#shopify-section-announcement_bar_slider {
  background: linear-gradient(135deg, #1a002f, #001f3f, #000814);
  border-bottom: 1px solid rgba(255,255,255,0.08);
  backdrop-filter: blur(12px);
  position: relative;
  overflow: hidden;
}

/* Animated Glow Overlay */
#shopify-section-announcement_bar_slider::before {
  content: "";
  position: absolute;
  width: 200%;
  height: 100%;
  background: linear-gradient(120deg, transparent, rgba(0,255,255,0.08), transparent);
  animation: shimmerMove 6s linear infinite;
}

@keyframes shimmerMove {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(50%); }
}

/* Container */
.hura-announcement-bar {
  width: 100%;
  max-width: 1250px;
  margin: 0 auto;
  padding: 12px 0;
  position: relative;
  z-index: 2;
}

/* Track */
.hura-announcement-bar .slick-track {
  display: flex;
  align-items: center;
}

/* Message */
.hura-announcement-bar .hura-message {
  text-align: center;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.5px;
  color: #ffffff;
  padding: 0 40px;
  transition: all 0.3s ease;
}

/* Hover Glow Effect */
.hura-announcement-bar .hura-message:hover {
  color: #00ffff;
  text-shadow: 0 0 10px rgba(0,255,255,0.8);
}

/* Links */
.announcement_link {
  color: #00ffff !important;
  text-decoration: none;
  font-weight: 600;
  transition: 0.3s ease;
}

.announcement_link:hover {
  color: #ffffff !important;
  text-shadow: 0 0 8px rgba(0,255,255,0.9);
}

/* Slick Navigation */
.slick-prev,
.slick-next {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: rgba(255,255,255,0.08);
  backdrop-filter: blur(6px);
  transition: all 0.3s ease;
  z-index: 3;
}

.slick-prev:hover,
.slick-next:hover {
  background: #00ffff;
  box-shadow: 0 0 15px rgba(0,255,255,0.9);
}

.slick-prev:before,
.slick-next:before {
  font-size: 14px;
  color: #ffffff;
  opacity: 1;
}

/* Arrow Position */
.slick-prev { left: -15px; }
.slick-next { right: -15px; }

/* ===== Mobile Optimization ===== */
@media screen and (max-width: 749px) {

  #shopify-section-announcement_bar_slider {
    background: linear-gradient(135deg, #0f0020, #001a33);
  }

  .hura-announcement-bar {
    padding: 14px 45px;
  }

  .hura-announcement-bar .hura-message {
    font-size: 12px;
    padding: 0 10px;
    line-height: 1.5;
  }

  .slick-prev,
  .slick-next {
    width: 26px;
    height: 26px;
  }

  .slick-prev { left: 5px; }
  .slick-next { right: 5px; }
}
</style>   


