<style>

/* ===== Drawer Button ===== */
header-drawer,
.header-drawer-lazyload {
  justify-self: start;
  height: 46px;
  width: 46px;
  margin-left: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  background: rgba(0,0,0,0.05);
  transition: all 0.3s ease;
}

header-drawer:hover,
.header-drawer-lazyload:hover {
  background: #000;
  transform: scale(1.05);
  box-shadow: 0 6px 15px rgba(0,0,0,0.15);
}

/* Hide on desktop */
@media screen and (min-width: 1024px) {
  header-drawer,
  .header-drawer-lazyload {
    display: none;
  }
}

/* ===== Search Placeholder Upgrade ===== */
input[type=search]::placeholder {
  color: rgba(0,0,0,0.5);
  font-weight: 500;
  transition: all 0.3s ease;
}

input[type=search]:focus::placeholder {
  opacity: 0.4;
  letter-spacing: 0.5px;
}

/* ===== Menu Container ===== */
.menu-drawer-container {
  display: flex;
  align-items: center;
}

/* ===== Menu List ===== */
.list-menu {
  list-style: none;
  padding: 0;
  margin: 0;
}

.list-menu--inline {
  display: inline-flex;
  gap: 25px;
  align-items: center;
}

/* ===== Menu Items ===== */
.list-menu__item {
  position: relative;
  align-items: center;
  font-weight: 500;
}

/* Link Style */
.list-menu__item--link {
  text-decoration: none;
  padding: 10px 0;
  color: #111;
  font-size: 15px;
  letter-spacing: 0.3px;
  transition: all 0.3s ease;
}

/* Underline Animation */
.list-menu__item--link::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 6px;
  width: 0%;
  height: 2px;
  background: #000;
  transition: width 0.3s ease;
}

.list-menu__item--link:hover {
  color: #000;
}

.list-menu__item--link:hover::after {
  width: 100%;
}

/* ===== Responsive ===== */
@media screen and (max-width: 749px) {
  .list-menu--inline {
    gap: 15px;
  }

  .list-menu__item--link {
    font-size: 14px;
  }
}

/* ===== Hidden Store Locator (future ready) ===== */
.my-store-locator {
  display: none;
}

</style>
