        <style>

/* ==============================
   BUTTON LOGIN & REGISTER
   Modern Glass Neon Style
============================== */

/* ===== Container ===== */
.button-login-daftar {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 14px;
}

/* ===== Base Button Style ===== */
.button-login-daftar a {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 14px 16px;
  font-size: 15px;
  font-weight: 600;
  border-radius: 14px;
  text-decoration: none;
  position: relative;
  overflow: hidden;
  transition: all 0.3s ease;
  letter-spacing: 0.5px;
  backdrop-filter: blur(8px);
}

/* ===== LOGIN BUTTON ===== */
.login,
.login-button {
  background: linear-gradient(135deg, #00f5a0, #00d9f5);
  color: #001b1f;
  box-shadow: 0 6px 18px rgba(0, 217, 245, 0.4);
}

/* ===== REGISTER BUTTON ===== */
.register,
.register-button {
  background: linear-gradient(135deg, #1a1a2e, #16213e);
  color: #00f5d4;
  border: 1px solid rgba(0, 245, 212, 0.6);
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.4);
}

/* ===== Hover Effect ===== */
.button-login-daftar a:hover {
  transform: translateY(-4px);
}

.login:hover {
  box-shadow: 0 10px 28px rgba(0, 217, 245, 0.7);
}

.register:hover {
  background: linear-gradient(135deg, #16213e, #0f3460);
  box-shadow: 0 10px 28px rgba(0, 245, 212, 0.5);
}

/* ===== Click Effect ===== */
.button-login-daftar a:active {
  transform: scale(0.96);
}

/* ===== Mobile Optimization ===== */
@media screen and (max-width: 768px) {
  .button-login-daftar {
    gap: 10px;
  }

  .button-login-daftar a {
    font-size: 14px;
    padding: 12px;
  }
}

@media screen and (max-width: 480px) {
  .button-login-daftar {
    grid-template-columns: 1fr;
  }
}

</style>
