               <style>

/* ===== Modern Search Container ===== */
.search-container {
  width: 100%;
  padding: 10px 15px;
  background: linear-gradient(135deg, #0f0f1a, #14142b);
}

/* Search Box Wrapper */
.container_search {
  position: relative;
  max-width: 600px;
  margin: 0 auto;
}

/* Input Styling */
.nosubmit_form input.nosubmit {
  width: 100%;
  height: 48px;
  padding: 0 50px 0 18px;
  border-radius: 50px;
  border: 1px solid rgba(0,255,255,0.2);
  background: rgba(255,255,255,0.05);
  backdrop-filter: blur(10px);
  color: #ffffff;
  font-size: 14px;
  font-weight: 500;
  transition: all 0.3s ease;
}

/* Placeholder */
.nosubmit_form input.nosubmit::placeholder {
  color: rgba(255,255,255,0.6);
}

/* Focus Effect */
.nosubmit_form input.nosubmit:focus {
  outline: none;
  border: 1px solid #00ffff;
  box-shadow: 0 0 15px rgba(0,255,255,0.5);
  background: rgba(0,255,255,0.05);
}

/* Search Icon */
.nosubmit_form::after {
  content: "🔍";
  position: absolute;
  right: 18px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 16px;
  pointer-events: none;
  opacity: 0.8;
}

/* Predictive Search Dropdown */
.predictive-search {
  background: #111827;
  border-radius: 15px;
  margin-top: 8px;
  border: 1px solid rgba(0,255,255,0.15);
  box-shadow: 0 10px 25px rgba(0,0,0,0.5);
  overflow: hidden;
}

/* Spinner Color */
.spinner .path {
  stroke: #00ffff;
}

/* Close Button */
.btn_close {
  position: absolute;
  right: -40px;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(0,255,255,0.15);
  border-radius: 50%;
  padding: 6px;
  transition: 0.3s ease;
}

.btn_close:hover {
  background: #00ffff;
  box-shadow: 0 0 10px rgba(0,255,255,0.7);
}

/* ===== Mobile Optimization ===== */
@media screen and (max-width: 749px) {

  .search-container {
    padding: 8px 10px;
  }

  .nosubmit_form input.nosubmit {
    height: 44px;
    font-size: 13px;
  }

  .btn_close {
    right: -30px;
  }

}

</style>
               <div class="search-container">
                  <div class="container_search container_search_port">
                     <predictive-search class="search-modal__form" data-loading-text="Loading...">
                        <form
                           class="nosubmit_form search search-modal__form"
                           action="/search"
                           id="nosubmit_form2"
                           method="get"
                           role="search"
                           >
                           <input type="hidden" name="type" value="product">
                           <input
                              class="nosubmit"
                              id="Search-In-Modal"
