<style>

/* ===============================
   FUTURISTIC FLOATING FOOTER
================================ */

.PIALASBO-fixed-footer {
  display: flex;
  justify-content: space-around;
  align-items: center;

  position: fixed;
  left: 12px;
  right: 12px;
  bottom: 18px;

  padding: 14px 12px;

  background: rgba(10, 18, 30, 0.85);
  backdrop-filter: blur(18px) saturate(160%);

  border-radius: 30px;

  box-shadow:
    0 20px 50px rgba(0,0,0,0.6),
    0 0 25px rgba(0,255,255,0.15);

  z-index: 999;
}

/* ===== FOOTER LINK ===== */
.PIALASBO-fixed-footer a {
  flex: 1;
  text-decoration: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  color: #dbeafe;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.4px;

  transition: all 0.3s ease;
  position: relative;
}

/* Hover Animation */
.PIALASBO-fixed-footer a:hover {
  color: #00f5ff;
  transform: translateY(-4px);
}

/* Icon Styling */
.PIALASBO-fixed-footer img {
  max-width: 22px;
  max-height: 22px;
  margin-bottom: 5px;
  transition: transform 0.3s ease, filter 0.3s ease;
}

/* Icon Hover */
.PIALASBO-fixed-footer a:hover img {
  transform: scale(1.15);
  filter: drop-shadow(0 0 8px rgba(0,255,255,0.8));
}

/* ===== CENTER BUTTON ===== */
.PIALASBO-fixed-footer .center {
  transform: translateY(-22px);
  background: linear-gradient(135deg, #00f5ff, #0066ff);
  padding: 16px;
  border-radius: 50%;
  box-shadow:
    0 0 20px rgba(0,255,255,0.8),
    0 10px 25px rgba(0,0,0,0.6);
  transition: all 0.3s ease;
}

/* Center Hover */
.PIALASBO-fixed-footer .center:hover {
  transform: translateY(-25px) scale(1.08);
}

/* Subtle Pulse Animation */
@keyframes pulseGlow {
  0% { box-shadow: 0 0 15px rgba(0,255,255,0.5); }
  50% { box-shadow: 0 0 28px rgba(0,255,255,1); }
  100% { box-shadow: 0 0 15px rgba(0,255,255,0.5); }
}

.PIALASBO-fixed-footer .center {
  animation: pulseGlow 2.5s infinite;
}

/* ===============================
   RESPONSIVE
================================ */

@media screen and (max-width: 768px) {

  .PIALASBO-fixed-footer {
    left: 8px;
    right: 8px;
    bottom: 14px;
    padding: 12px 8px;
  }

  .PIALASBO-fixed-footer a {
    font-size: 11px;
  }

  .PIALASBO-fixed-footer img {
    max-width: 20px;
  }

}

@media screen and (max-width: 480px) {

  .PIALASBO-fixed-footer {
    border-radius: 22px;
  }

  .PIALASBO-fixed-footer .center {
    padding: 14px;
  }

}

