            <script>
               RP(document).ready(function() {
                 RP(document).on('click', '#apple-care-add', function (event) {
                   var isChecked = RP('#add-apple-care').is(':checked');
                   if (isChecked) {
                     RP('#add-apple-care').prop('checked', false);
                     RP("#apple-care-add .pdp-care-btn").html("Add");
                     // RP("#apple-added-if").val("");
                   } else {
                     RP('#add-apple-care').prop('checked', true);
                     RP("#apple-care-add .pdp-care-btn").html("Added");
                     // RP("#apple-added-if").val("added");
                   }
                   var appleCareID = RP(this).attr("data-index");
                   RP("#apple-care-varid").val(appleCareID);
                   updatePriceAfterAddingCareOrWarranty();
                 });
                 RP(document).on('click', '#secWarranty-add', function (event) {
                   var isChecked2 = RP('#add-secWarranty').is(':checked');
                   if (isChecked2) {
                     RP('#add-secWarranty').prop('checked', false);
                     RP("#secWarranty-add .pdp-secWarranty-btn").html("Add");
                   } else {
                     RP('#add-secWarranty').prop('checked', true);
                     RP("#secWarranty-add .pdp-secWarranty-btn").html("Added");
                     // RP("#apple-added-if").val("added");
                   }
                   var secWarrantyID = RP(this).attr("data-index");
                   RP("#secWarranty-varid").val(secWarrantyID);
                   updatePriceAfterAddingCareOrWarranty();
                 });
               
                 // Reset trade-in values to 0
                 RP(document).on('click', '#no-trade-in', () => {
                   const RPtradeInValueAmounts = document.querySelectorAll('.js-trade-in-value-amount');
                   const RPstartTradeInBtn = document.querySelector('.js-product-option-form .js-trade-in-modal-trigger-input');
                   const RPstartTradeInBtnLabel = document.querySelector('.js-product-option-form .js-trade-in-modal-trigger-input + label');
                   const RPhiddenSelectedTradeIn = document.querySelector('#selected-trade-in-value');
                   const RPproductPrices = document.querySelectorAll('.js-product-price-with-care-warranty');
               
                   RPtradeInValueAmounts.forEach((RPtradeInValueAmount) => {
                     if (RPtradeInValueAmount.classList?.contains('pdp-value-amount')) {
                       RPtradeInValueAmount.innerText = 'RP0';
                       RPtradeInValueAmount.setAttribute('data-trade-in-value', 0);
                       RPtradeInValueAmount.parentElement?.classList?.add('hidden');
                     }
                   });
               
                   RPstartTradeInBtnLabel.innerText = 'Start trade-in';
                   RPhiddenSelectedTradeIn.value = 0;
               
                   updatePriceAfterRemovingTradeIn();
                 });
               
                 function updatePriceAfterRemovingTradeIn() {
                   const isAppleCareAdded = RP('#add-apple-care').is(':checked');
                   const isWarrantyAdded = RP('#add-secWarranty').is(':checked');
                   const isTradeInAdded = document.querySelector('#selected-trade-in-value')?.value;
                   const RPproductPrices = document.querySelectorAll('.js-product-price-with-care-warranty');
               
                   RP('.js-product-price-with-care-warranty').each((i, RPproductPrice) => {
                     const price = RP(RPproductPrice).data('price');
                     let updatedPrice;
               
                     /* TO BE ADDED */
                     if (isTradeInAdded && isAppleCareAdded && isWarrantyAdded) {
                       updatedPrice = RP(RPproductPrice).attr('data-price-with-care-and-secWarranty');
                     } else if (isTradeInAdded && isAppleCareAdded) {
                       updatedPrice = RP(RPproductPrice).attr('data-price-with-care');
                     } else if (isTradeInAdded && isWarrantyAdded) {
                       updatedPrice = RP(RPproductPrice).attr('data-price-with-secWarranty');
                     } else if (isTradeInAdded) {
                       updatedPrice = price;
                     } else {
                       updatedPrice = price;
                     }
               
                     RP(RPproductPrice).html(updatedPrice);
                   });
                 }
               
                 function updatePriceAfterAddingCareOrWarranty() {
                   const isAppleCareAdded = RP('#add-apple-care').is(':checked');
                   const isWarrantyAdded = RP('#add-secWarranty').is(':checked');
                   const hasTradeIn = RP('#selected-trade-in-value').val() && RP('#selected-trade-in-value').val() !== '0' && RP("#selected-trade-in-device").val() !== '';
                   const hiddenSelectedTradeInValue = RP('#selected-trade-in-value').val();
                   const tradeInPrice = hiddenSelectedTradeInValue
                     ? formatMoney(hiddenSelectedTradeInValue)
                     : 0;
               
                   RP('.js-product-price-with-care-warranty').each(function(i, RPproductPrice) {
                     let price = RP(this).attr('data-price');
                     const nmpPriceCalculation = RP(this).data('priceCalculation');
               
                     if (isAppleCareAdded && isWarrantyAdded && hasTradeIn) {
                       price = setPriceWithTradeIn('data-price-with-care-and-secWarranty', RPproductPrice);
                     } else if (isAppleCareAdded && isWarrantyAdded) {
                       price = RP(this).attr('data-price-with-care-and-secWarranty');
                     } else if (isAppleCareAdded && hasTradeIn) {
                       price = setPriceWithTradeIn('data-price-with-care', RPproductPrice);
                     } else if (isWarrantyAdded && hasTradeIn) {
                       price = setPriceWithTradeIn('data-price-with-secWarranty', RPproductPrice);
                     } else if (isAppleCareAdded) {
                       price = RP(this).attr('data-price-with-care');
                     } else if (isWarrantyAdded) {
                       price = RP(this).attr('data-price-with-secWarranty');
                     } else if (hasTradeIn) {
                       price = setPriceWithTradeIn('data-price', RPproductPrice);
                     }
               
                     RP(this).html(price);
                   });
                 }
               
                 function setCookie(name, value, days) {
                   var expires = "";
                   if (days) {
                     var date = new Date();
                     date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
                     expires = "; expires=" + date.toUTCString();
                   }
                   document.cookie = name + "=" + (value || "") + expires + "; path=/";
                 }
               
                 function getCookie(name) {
                   var nameEQ = name + "=";
                   var ca = document.cookie.split(';');
                   for (var i = 0; i < ca.length; i++) {
                     var c = ca[i];
                     while (c.charAt(0) == ' ') c = c.substring(1, c.length);
                     if (c.indexOf(nameEQ) == 0) return c.substring(nameEQ.length, c.length);
                   }
                   return null;
                 }
               
                 function eraseCookie(name) {
                   document.cookie = name + '=; Path=/; Expires=Thu, 01 Jan 1970 00:00:01 GMT;';
                 }
               
                 //added by anusha - 4th variant option cookie approach - start
               
                 //check if the main product is inside 4th option product list. if its present, set cookie array
                 var pid = "8004323737780";
                 var pid1 = "";
                 var pid1 = pid1.replace(/s/g, "");
                 var pid2 = pid1.split('-');
                 var count = 0;
                 for (var j = 0; j < pid2.length; j++) {
                   var a = pid2[j];
                   var b = pid;
                   if (a.trim() == b.trim()) {
                     count++;
                   }
                 }
                 if (count > 0) {
                   setCookie('optionPIDlist', pid2.join('|'), {
                     path: '/'
                   });
                 }
               
                 // if the main product has 'empty 4th product list', then delete all the cookies
                 if (!pid1.length > 0) {
                   eraseCookie('option1select');
                   eraseCookie('option2select');
                   eraseCookie('option3select');
                   eraseCookie('optionPIDlist');
                 }
               
                 // cookie values - 3 options
                 let op1 = getCookie('option1select');
                 let op2 = getCookie('option2select');
                 let op3 = getCookie('option3select');
               
                 // when customer change the 4th option selection - trigger click event (inorder to set cookie values for 3 options)
                 if (op1 && RP('fieldset.product-form__input[data-opcount="1"]').length > 0) {
                   setTimeout(function() {
                     RP('fieldset.product-form__input[data-opcount="1"]').find('label[data-title="' + op1 + '"]').trigger('click');
                   }, 1000);
                 };
                 if (op2 && RP('fieldset.product-form__input[data-opcount="2"]').length > 0) {
                   setTimeout(function() {
                     RP('fieldset.product-form__input[data-opcount="2"]').find('label[data-title="' + op2 + '"]').trigger('click');
                   }, 1000);
                 };
                 if (op3 && RP('fieldset.product-form__input[data-opcount="3"]').length > 0) {
                   setTimeout(function() {
                     RP('fieldset.product-form__input[data-opcount="3"]').find('label[data-title="' + op3 + '"]').trigger('click');
                   }, 1000);
                 };
               
                 let op11 = RP("input[type='radio'][name='Title']:checked").val();
                 let op22 = RP("input[type='radio'][name='']:checked").val();
                 let op33 = RP("input[type='radio'][name='']:checked").val();
               
                 // when customer dont click on any of the variant buttons - set cookie values for 3 options from current mainprod variant selection
                 if (op1 == null && op2 == null && op3 == null) {
                   if (op11 && RP('fieldset.product-form__input[data-opcount="1"]').length > 0) {
                     setTimeout(function() {
                       RP('fieldset.product-form__input[data-opcount="1"]').find('label[data-title="' + op11 + '"]').trigger('click');
                     }, 1000);
                   };
                   if (op22 && RP('fieldset.product-form__input[data-opcount="2"]').length > 0) {
                     setTimeout(function() {
                       RP('fieldset.product-form__input[data-opcount="2"]').find('label[data-title="' + op22 + '"]').trigger('click');
                     }, 1000);
                   };
                   if (op33 && RP('fieldset.product-form__input[data-opcount="3"]').length > 0) {
                     setTimeout(function() {
                       RP('fieldset.product-form__input[data-opcount="3"]').find('label[data-title="' + op33 + '"]').trigger('click');
                     }, 1000);
                   };
                   if (getCookie('optionPIDlist')) {
                     setCookie('option1select', op11, 7);
                     setCookie('option2select', op22, 7);
                     setCookie('option3select', op33, 7);
                   }
                 }
                 // added by anusha - 4th variant option cookie approach - end
               
                 if (vat_free_day == true) {
                   var vat_price_footer = RP(".pricestyle").find(".vat_price_bold").text();
                   if (vat_price_footer != "") {
                     RP("#price-element").find(".footerOr2").css("display", "none");
                   }
                 }
               });
            </script>
            <script>
               RP(document).on('change', 'input[type="number"]', function (event) {
                 this.value = this.value.replace(/[^0-9]+/g, '');
                 if (this.value < 1) this.value = 0;
               });
               RP(document).on('keypress', 'input[type="number"]', function (event) {
                 if (
                   (event.target.value.length == 0 && event.which == 48) ||
                   (event.target.value.length == 0 && event.which > 31 && event.which < 48) ||
                   (event.target.value.length == 0 && event.which > 57 && event.which < 128)
                 ) {
                   return false;
                 }
               });
               RP(document).on('keypress', 'input[type="number"]', function (event) {
                 return (((event.which > 47) && (event.which < 58)) || (event.which == 13));
               });
               
               // reload page on back button click since the cached version on Safari browsers is incorrect
               RP(window).bind("pageshow", function(event) {
                 if (event.originalEvent.persisted) {
                   window.location.reload();
                 }
               });
            </script>
