                     class="product-recommendations__cta hidden"
                     style="height:0px;"
                     >
                     <input type="hidden" id="prod_currency" value="IDR">
                     <button
                        type="submit"
                        class="button-cart-frequent card-btn-1 product-form__submit button button--full-width js-frequent-submit"
                        id="card-button"
                        class="frq-card-btn"
                        >
                        Add&nbsp; <span id="checked-products"> </span> &nbsp;Items to Cart
                        <div class="loading-overlay__spinner-frequent hidden">
                           <svg
                              aria-hidden="true"
                              focusable="false"
                              role="presentation"
                              class="spinner"
                              viewBox="0 0 66 66"
                              xmlns="http://www.w3.org/2000/svg"
                              >
                              <circle class="path" fill="none" stroke-width="6" cx="33" cy="33" r="30"></circle>
                           </svg>
                        </div>
                     </button>
                  </div>
               </product-recommendations>
            </div>
            <script>
               class ProductRecommendations extends HTMLElement {
                 constructor() {
                   super();
                   this.config = {
                     dom: {
                       button: '.js-frequent-submit',
                       input: '.js-frequent-products-checkbox',
                       selected: 'input[name="frequent-products-pdp"]:checked',
                     },
                     cls: {
                       hide: 'hide',
                     },
                   };
                   const handleIntersection = (entries, observer) => {
                     if (!entries[0].isIntersecting) return;
                     observer.unobserve(this);
                     fetch(this.dataset.url)
                       .then((response) => response.text())
                       .then((text) => {
                         const html = document.createElement('div');
                         html.innerHTML = text;
                         const recommendations = html.querySelector('product-recommendations');
                         if (recommendations && recommendations.innerHTML.trim().length) {
                           this.innerHTML = recommendations.innerHTML;
                         }
                         if (html.querySelector('.grid__item')) {
                           this.classList.add('product-recommendations--loaded');
                         }
               
                         this.addEvent();
                         call_gafunction();
                       })
                       .catch((e) => {
                         console.error(e);
                       });
                   };
                   new IntersectionObserver(handleIntersection.bind(this), { rootMargin: '0px 0px 200px 0px' }).observe(this);
                 }
                 hideButton(el) {
                   if (!el) return;
                   el.classList.add(this.config.cls.hide);
                 }
                 showButton(el) {
                   if (!el) return;
                   el.classList.remove(this.config.cls.hide);
                 }
                 updateButtonState(show = true) {
                   const RPbutton = this.querySelector(this.config.dom.button) || null;
                   if (!RPbutton) return;
               
                   if (show) {
                     this.showButton(RPbutton);
                   } else {
                     this.hideButton(RPbutton);
                   }
                 }
                 addEvent() {
                   const RPinputs = this.querySelectorAll(this.config.dom.input) || [];
               
                   if (!RPinputs?.length > 0) return;
                   [...RPinputs].forEach((RPinput) => {
                     RPinput.addEventListener('change', () => {
                       const RPselected = this.querySelector(this.config.dom.selected) || null;
               
                       if (RPselected) {
                         this.updateButtonState();
                       } else {
                         this.updateButtonState(false);
                       }
                     });
                   });
                 }
               }
               customElements.define('product-recommendations', ProductRecommendations);
               
               function call_gafunction() {
                 var mpn_handle = RP('#mpn_handle').val();
                 var frequentProducts_ga = [];
                 var productList = 'Shopify Rec :: ' + mpn_handle;
                 RP.each(RP("input[name='frequent-products-pdp']"), function () {
                   var prodtitle = RP('#title_' + RP(this).val()).val();
                   var prodMPN = RP('#product_mpn_handle_' + RP(this).val()).val();
                   var prodType = RP('.card_product_category_' + RP(this).val()).val();
                   var prodCurrency = RP('.card_product_currency_' + RP(this).val()).attr('value');
                   var prodPrice = RP('.card_product_price_' + RP(this).val()).attr('value');
                   var prodSku = RP('.card_product_sku_' + RP(this).val()).attr('value');
                   var compareprice = RP('.card_product_compare_' + RP(this).val()).attr('value');
                   prodPrice = Number(prodPrice.replace(/[^0-9.-]+/g, ''));
                   var discount = 0;
                   if (compareprice != '') {
                     compareprice = Number(compareprice.replace(/[^0-9.-]+/g, ''));
                     discount = parseFloat(compareprice) - parseFloat(prodPrice);
                     discount = parseFloat(discount);
                     // prodPrice = compareprice;
                   }
                   var productPrice1 = parseFloat(prodPrice);
                   item_ga = {};
                   item_ga['item_id'] = prodSku;
                   item_ga['item_name'] = prodtitle;
                   item_ga['item_category'] = prodType;
                   item_ga['item_list_name'] = productList;
                   item_ga['price'] = prodPrice;
                   item_ga['quantity'] = 1;
                   frequentProducts_ga.push(item_ga);
                 });
                 if (frequentProducts_ga.length != 0) {
                   dataLayer.push({ ecommerce: null });
                   dataLayer.push({
                     event: 'view_item_list',
                     ecommerce: {
                       item_list_name: productList,
                       items: frequentProducts_ga,
                     },
                   });
                 }
               }
            </script>
            <script>
               RP(document).ready(function () {
                 RP(window).on('scroll', function () {
                   if (
                     RP(window).scrollTop() >=
                     RP('.product-recommendations1').offset().top + RP('.product-recommendations1').outerHeight() - window.innerHeight
                   ) {
                     setTimeout(function () {
                       var checkLength = RP("input[name='frequent-products-pdp']:checked").length;
                       var productRecs = document.querySelector('.product-recommendations1');
               
                       RP('#checked-products').text(checkLength);
                     }, 4000);
                     setTimeout(function () {
                       var height;
                       var maxheight = 0;
                       var minheight = 0;
                       RP('.price_container_cal').each(function () {
                         height = parseInt(RP(this).height());
                         if (height > maxheight) {
                           maxheight = height;
                         } else {
                           minheight = height;
                         }
                       });
                       let isMobile = window.matchMedia('only screen and (max-width: 1023px)').matches;
                       if (!isMobile) {
                         if (maxheight >= minheight) {
                           RP('.price_container_cal').attr(
                             'style',
                             'display: flex; flex-flow: column; justify-content: flex-end; height:' + maxheight + 'px;'
                           );
                         }
                       }
                     }, 500);
                   }
                 });
               });
            </script>
