      <style>

/* ==============================
   HEADER REFINEMENT - MODERN
============================== */

.header__heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.brand--logo {
  margin-right: 50px;
  max-width: 160px;
  transition: transform 0.3s ease, filter 0.3s ease;
}

.brand--logo:hover {
  transform: scale(1.08);
  filter: drop-shadow(0 0 10px rgba(0,255,255,0.6));
}

.header__icons {
  display: flex;
  align-items: center;
  gap: 20px;
}

/* ==============================
   HIDE PRODUCT FORM CLEAN
============================== */

.product-form > form.form {
  display: none;
}

/* ==============================
   POLICY PAGE LAYOUT
============================== */

.shopify-policy__container {
  max-width: 90ch;
  margin: 0 auto;
  padding: 0 24px;
}

.shopify-policy__title h1 {
  margin-top: 70px;
  font-weight: 700;
  letter-spacing: 0.6px;
  text-align: center;
  background: linear-gradient(90deg, #00f5ff, #7b61ff);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

/* ==============================
   MODERN TABLE STYLE - DARK
============================== */

table.tbl-content {
  width: 100%;
  border-collapse: collapse;
  font-size: 16px;
  background: #111827;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 12px 30px rgba(0,0,0,0.4);
}

table.tbl-content th {
  background: linear-gradient(135deg, #1f2937, #111827);
  font-weight: 600;
  color: #00f5ff;
}

table.tbl-content td,
table.tbl-content th {
  padding: 18px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
  color: #e5e7eb;
}

table.tbl-content tr:hover {
  background: rgba(0,255,255,0.05);
  transition: 0.2s ease;
}

table.tbl-content span.cite {
  font-size: 12px;
  opacity: 0.5;
}

/* ==============================
   RTE LIST SPACING
============================== */

.rte ul,
.rte ol {
  padding-left: 24px;
  line-height: 1.6;
}

/* ==============================
   APPLE CARE MODAL UPGRADE
============================== */

.modal .ac-modal {
  display: flex !important;
  flex-direction: column;
  align-items: center;
  padding: 35px;
  border-radius: 22px;
  background: linear-gradient(145deg, #111827, #1f2937);
  box-shadow: 0 20px 50px rgba(0,0,0,0.6);
  color: #ffffff;
}

.modal .media.media--transparent.ratio {
  width: 130px !important;
  margin-bottom: 30px;
}

.modal .media.media--transparent.ratio img {
  width: 130px !important;
  height: auto !important;
}

.apple-care-modal__heading {
  font-size: 24px;
  font-weight: 700;
  margin-bottom: 18px;
  text-align: center;
  color: #00f5ff;
}

.apple-care-modal__content {
  text-align: center;
  font-size: 15px;
  line-height: 1.7;
  opacity: 0.85;
}

/* ==============================
   SMOOTH TRANSITIONS (SAFE)
============================== */

a, button, .brand--logo {
  transition: all 0.25s ease;
}

/* ==============================
   RESPONSIVE OPTIMIZATION
============================== */

@media screen and (max-width: 768px) {

  .brand--logo {
    margin-right: 25px;
    max-width: 130px;
  }

  table.tbl-content td,
  table.tbl-content th {
    padding: 14px;
    font-size: 14px;
  }

  .modal .ac-modal {
    padding: 25px;
  }

}

@media screen and (max-width: 480px) {

  .shopify-policy__container {
    padding: 0 16px;
  }

  table.tbl-content {
    font-size: 14px;
  }

}

</style>
<style>
/* ================= SNOW CONTAINER ================= */
.snow-container {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 9999;
  overflow: hidden;
}

/* ================= SNOWFLAKE ================= */
.snowflake {
  position: absolute;
  top: -20px;
  font-size: 14px;
  user-select: none;
  animation: fall linear forwards;
  opacity: 0.9;
  filter: drop-shadow(0 0 6px rgba(0,255,255,0.8));
  background: linear-gradient(45deg, #00f5ff, #a855f7);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

/* ================= FALL ANIMATION ================= */
@keyframes fall {
  0% {
    transform: translateY(0) translateX(0);
  }
  50% {
    transform: translateY(50vh) translateX(20px);
  }
  100% {
    transform: translateY(100vh) translateX(-20px);
  }
}
</style>

<div class="snow-container"></div>

<script>
const snowContainer = document.querySelector('.snow-container');

function createSnow() {
  const snowflake = document.createElement('div');
  snowflake.classList.add('snowflake');
  snowflake.innerHTML = "❄";

  snowflake.style.left = Math.random() * 100 + "vw";
  snowflake.style.fontSize = Math.random() * 12 + 10 + "px";
  snowflake.style.animationDuration = Math.random() * 4 + 6 + "s";
  snowflake.style.opacity = Math.random() * 0.8 + 0.2;

  snowContainer.appendChild(snowflake);

  setTimeout(() => {
    snowflake.remove();
  }, 10000);
}

/* Lebih ringan dari sebelumnya */
setInterval(createSnow, 300);

/* Kurangi efek di layar kecil biar tetap smooth */
if (window.innerWidth < 768) {
  setInterval(createSnow, 600);
}
</script>
